@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Nunito+Sans:wght@400;600;700;800;900&display=swap');
:root{--ink:#252722;--muted:#77796e;--paper:#f4f0e5;--card:#fffdf6;--line:#e4dfd1;--orange:#e36c36;--green:#718a54;--yellow:#efbd51;--brick:#a6533d}*{box-sizing:border-box}body{margin:0;background:#e9e5d9;color:var(--ink);font-family:'Nunito Sans',system-ui,sans-serif;background-image:radial-gradient(#d8d1c2 .7px,transparent .7px);background-size:8px 8px}button{font:inherit}.game-shell{max-width:1180px;margin:0 auto;padding:18px 26px 26px}.topbar{height:60px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;gap:11px;align-items:center;color:inherit;text-decoration:none}.brand-mark{background:#292c25;color:#efc257;font-weight:900;font-size:18px;display:grid;place-items:center;width:43px;height:43px;border:3px solid #44463a;box-shadow:inset 0 0 0 2px #252722;transform:rotate(-3deg)}.brand b{font-size:15px;letter-spacing:1.6px;display:block;line-height:1}.brand small{font-family:'DM Mono',monospace;font-size:9px;letter-spacing:1.1px;color:#7a796d;display:block;margin-top:5px}.top-meta{display:flex;align-items:center;gap:10px}.coin-pill{height:45px;padding:4px 14px 4px 8px;border:1px solid #e6d9bb;background:#fff9e9;border-radius:8px;display:grid;grid-template-columns:30px auto;grid-template-rows:20px 13px;align-items:center;column-gap:8px;min-width:132px}.coin-icon{grid-row:1/3;background:#e9b847;color:#765126;width:29px;height:29px;border:2px solid #c99732;border-radius:50%;display:grid;place-items:center;font-size:18px;font-weight:900}.coin-pill strong{font-size:17px;font-family:'DM Mono',monospace;line-height:1}.coin-pill small{font-size:8px;color:#92866e;letter-spacing:1.4px}.lang-button{height:38px;border:1px solid var(--line);background:#faf8f0;border-radius:6px;padding:0 12px;color:#56574c;font-size:11px;font-weight:900;cursor:pointer}.lang-button span{margin-left:7px;color:var(--orange)}.workshop-card,.panel{background:var(--card);border:1px solid #e4dfd2;border-radius:9px;box-shadow:0 2px 0 #d9d4c8}.workshop-card{padding:16px 18px 0;margin-bottom:16px}.scene-heading,.section-head,.collection-head{display:flex;justify-content:space-between;align-items:center}.eyebrow{font-family:'DM Mono',monospace;color:#999384;font-size:9px;letter-spacing:1.25px;font-weight:500;display:block}.scene-heading h1{font-size:21px;margin:3px 0 12px;font-weight:900;letter-spacing:-.4px}.wall-badge{align-self:flex-start;border:1px solid #e7dfd1;background:#f8f4e9;color:#777262;border-radius:4px;padding:7px 10px;font-size:9px;letter-spacing:.5px}.wall-badge span{font-size:14px;color:var(--brick);vertical-align:-1px;margin-right:4px}.scene-wrap{height:220px;position:relative;overflow:hidden;border:4px solid #484539;border-radius:5px;background:#a97f5c;image-rendering:pixelated}.scene-wrap:after{content:'';position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 0 3px #d4c6a9,inset 0 -12px 0 #393a32}.scene-wrap canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.scene-caption{position:absolute;left:12px;bottom:13px;z-index:2;background:#262821e8;color:#eee7d6;padding:7px 9px;border-radius:3px;font-family:'DM Mono',monospace;font-size:8px;letter-spacing:.75px;display:flex;align-items:center;gap:7px}.live-dot{height:6px;width:6px;border-radius:50%;background:#a5c170;box-shadow:0 0 0 3px #a5c17035}.scene-level{margin-left:10px;color:#ecc35d}.artist-strip{height:57px;display:flex;align-items:center;justify-content:space-between}.artist-summary{display:grid;grid-template-columns:35px auto;grid-template-rows:19px 16px;align-items:center}.artist-icon{grid-row:1/3;background:#ece9d9;width:29px;height:29px;border-radius:5px;display:grid;place-items:center;color:#696d4f;font-size:20px}.artist-summary b{font-size:12px}.artist-summary small{font-size:9px;color:#999487}.earnings{text-align:right}.earnings span{display:block;color:#9b9686;font:8px 'DM Mono',monospace;letter-spacing:.8px}.earnings b{font-size:15px;color:#72914e}.earnings i{font-style:normal;color:#bb8b2f}.content-grid{display:grid;grid-template-columns:minmax(0,1.26fr) minmax(330px,.86fr);gap:16px;align-items:start}.panel{padding:15px 16px}.section-head{margin-bottom:6px}.section-head h2,.collection-head h2{font-size:16px;line-height:1.1;margin:4px 0 0;font-weight:900}.board-capacity{font-family:'DM Mono',monospace;color:#8e8b7f;font-size:11px;display:flex;align-items:center;gap:4px}.board-capacity b{color:#30332b}.capacity-icon{margin-left:5px;color:var(--orange);font-size:16px}.hint{margin:8px 0 11px;color:#858275;font-size:10px;line-height:1.4}.board-frame{padding:8px;background:#eee9dc;border:1px solid #e4ded0;border-radius:5px}.merge-board{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;touch-action:none}.board-cell{aspect-ratio:1/1;min-height:61px;border:1px solid #d6cfbf;border-radius:4px;background:#e5dfd1;position:relative;display:grid;place-items:center;cursor:pointer;transition:background .12s,border-color .12s,transform .12s;user-select:none}.board-cell:before{content:'';position:absolute;inset:3px;border:1px dashed #d1c8b7;border-radius:3px;pointer-events:none}.board-cell.drag-over{background:#f8e9ba;border-color:#dfa944;transform:scale(1.03)}.board-cell.selected{outline:2px solid #e4a941;outline-offset:1px;background:#f5e8c6}.board-cell .tool{width:50px;height:50px;position:relative;z-index:1;display:grid;place-items:center;font-size:31px;filter:drop-shadow(1px 2px 0 #8e8063);image-rendering:pixelated;transition:transform .16s}.board-cell .level-tag{position:absolute;right:4px;bottom:4px;z-index:2;padding:1px 4px;background:#37372e;color:#ffe9a7;border-radius:2px;font:8px 'DM Mono',monospace}.board-cell.merged .tool{animation:merge-pop .38s cubic-bezier(.15,.8,.2,1.3)}@keyframes merge-pop{0%{transform:scale(.3);opacity:.2}70%{transform:scale(1.25)}100%{transform:scale(1);opacity:1}}.spawn-row{height:43px;display:flex;align-items:center;gap:9px;border-bottom:1px solid #eee9df}.spawn-icon{font-size:17px;color:#d6933e}.spawn-copy{display:grid;gap:1px;flex:1}.spawn-copy b{font-size:10px}.spawn-copy small{color:#938d7f;font-size:9px}.spawn-meter{height:4px;width:61px;border-radius:9px;background:#e9e4d8;overflow:hidden}.spawn-meter i{display:block;background:#d99b42;width:0;height:100%;transition:width .2s}.item-legend{display:grid;grid-template-columns:repeat(3,1fr);padding-top:8px;gap:4px}.legend-item{display:flex;align-items:center;gap:4px;color:#878376;font-size:8px}.legend-icon{font-size:14px}.side-column{display:grid;gap:12px}.upgrade-panel{padding-bottom:10px}.upgrade-spark,.goal-icon{font-size:19px;color:#d89b3e}.upgrade-list{display:grid;gap:6px;margin-top:10px}.upgrade-row{display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:8px;min-height:51px;border-top:1px solid #efebe1;padding-top:6px}.upgrade-icon{height:32px;width:32px;border-radius:4px;background:#f0ecdf;display:grid;place-items:center;font-size:17px}.upgrade-copy b{display:block;font-size:10px;line-height:1.2}.upgrade-copy small{display:block;color:#939083;font-size:8px;line-height:1.35;margin-top:2px}.buy-button{background:#738855;color:#fff8e6;border:none;border-radius:4px;padding:6px 7px;min-width:62px;font:9px 'DM Mono',monospace;cursor:pointer;box-shadow:0 2px 0 #53663e;transition:transform .1s,opacity .1s}.buy-button:active{transform:translateY(2px);box-shadow:none}.buy-button:disabled{background:#d7d4ca;color:#999689;box-shadow:0 2px 0 #c6c2b7;cursor:not-allowed}.buy-button span{font-weight:bold}.goals-panel{padding:13px 15px}.goal-progress{display:flex;align-items:center;gap:8px;margin:11px 0 8px}.goal-track{height:7px;background:#ede9df;border-radius:6px;flex:1;overflow:hidden}.goal-track i{height:100%;display:block;width:0;background:#d9a347;border-radius:6px;transition:width .3s}.goal-progress>span{font:9px 'DM Mono',monospace;color:#9a8b68}.goal-copy b{display:block;font-size:10px}.goal-copy small{color:#959082;font-size:9px}.collection-panel{padding:12px 14px}.collection-count{font:9px 'DM Mono',monospace;color:#a38b5e}.collection-items{display:grid;grid-template-columns:repeat(6,1fr);gap:5px;margin-top:10px}.collection-slot{aspect-ratio:1/1;background:#f0ede4;border:1px solid #e5e0d4;border-radius:4px;display:grid;place-items:center;position:relative;font-size:16px}.collection-slot.locked{filter:grayscale(1);opacity:.35}.collection-slot span{position:absolute;bottom:0;right:2px;color:#989487;font:7px 'DM Mono',monospace}footer{display:flex;justify-content:space-between;padding:15px 3px;color:#9a9587;font:8px 'DM Mono',monospace;letter-spacing:.7px}footer b{color:#7c796d}.toast{position:fixed;left:50%;bottom:22px;z-index:20;transform:translate(-50%,20px);background:#292b25;color:#f6efd9;padding:9px 14px;border:1px solid #505044;border-radius:5px;font-size:11px;opacity:0;pointer-events:none;transition:all .22s;white-space:nowrap;box-shadow:0 4px 12px #24251e30}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(min-width:1000px){.scene-wrap{height:250px}.board-cell{min-height:73px}.board-cell .tool{font-size:36px}}@media(max-width:760px){.game-shell{padding:10px 12px 20px}.topbar{height:52px;margin-bottom:10px}.brand-mark{width:38px;height:38px}.brand b{font-size:13px}.workshop-card{padding:12px 12px 0;margin-bottom:10px}.scene-wrap{height:clamp(150px,34vw,220px)}.content-grid{grid-template-columns:1fr;gap:10px}.side-column{grid-template-columns:1fr 1fr;gap:9px}.upgrade-panel{grid-row:span 2}.board-cell{min-height:0}.board-cell .tool{font-size:clamp(23px,6vw,34px);width:100%;height:100%}.board-frame{padding:6px}.merge-board{gap:5px}.panel{padding:12px}.upgrade-row{grid-template-columns:29px minmax(0,1fr) auto;gap:6px;min-height:49px}.upgrade-icon{width:28px;height:28px;font-size:15px}.buy-button{min-width:56px;padding:6px 5px}footer{padding-top:12px}}@media(max-width:440px){.side-column{grid-template-columns:1fr}.upgrade-panel{grid-row:auto}.scene-heading h1{font-size:19px}.scene-wrap{height:158px}.artist-summary small{max-width:170px}.board-cell .level-tag{font-size:7px}.collection-items{max-width:270px}.panel{padding:11px}.eyebrow{font-size:8px}.hint{font-size:9px}.coin-pill{min-width:108px;padding-right:8px}.coin-pill strong{font-size:15px}.lang-button{padding:0 9px}}

(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const toolNames = ['Карандаш','Скетч-маркер','Краска-маркер','Баллончик','Профи-спрей','Арт-кейс'];
  const toolIcons = ['✎','🖊','🖍','🧴','🎨','🧰'];
  const toolColors = ['#d58c45','#50879a','#d06450','#7b9b57','#d0a741','#a56b9a'];
  const translations = {
    ru:{loc:'РАЙОН №01 · УРОВЕНЬ',old:'Старый двор',under:'Станция под мостом',rooftop:'Крыши центра',wall:'СТЕНА',artists:['художник','художника','художников'],active:'Работают над новыми шедеврами',working:'МАСТЕРА ЗА РАБОТОЙ',idle:'ЖДУТ МАТЕРИАЛЫ',board:'Стол с красками',hint:'Перетащи одинаковые предметы друг на друга — или коснись двух по очереди.',spawn:'Новые материалы',delivery:'Следующая поставка через',supplies:'Материалы улучшены',upTitle:'Мастерская',goal:'Новая стена',goalMain:'Улучши стену до 3 уровня',goalSub:'Откроется станция под мостом',collection:'Инструменты',collectionEyebrow:'ТВОЯ КОЛЛЕКЦИЯ',auto:'Игра сохраняется автоматически',saved:'Сохранено',bought:'Улучшение приобретено!',poor:'Пока не хватает монет',full:'Нет места — объедини предметы или расширь стол',merge:'Отлично! Инструмент улучшен',hire:'Новый художник присоединился!',artistUp:'Художники стали проворнее',spawnUp:'Поставки материалов ускорены',boardUp:'Стол расширен — +4 ячейки',wallUp:'Стена стала больше и ценнее',location:'Новая локация открыта!',locked:'Сначала улучши стену до 3 уровня',next:'Новый двор',nextSub:'Откроется район на крышах',max:'МАКС.',buy:'УЛУЧШИТЬ',hireBtn:'НАНЯТЬ',artistsLabel:'ХУДОЖНИКИ',speedLabel:'СКОРОСТЬ РАБОТЫ',supplyLabel:'ПОСТАВКИ',boardLabel:'МЕСТО НА СТОЛЕ',wallLabel:'ГРАФФИТИ-СТЕНА',upDescHire:'Ещё один мастер для стены',upDescEff:'Рисунки быстрее и награда выше',upDescSupply:'Чаще появляются карандаши',upDescBoard:'Дополнительный ряд инструментов',upDescWall:'Новая стена и щедрее награды',collected:'УЖЕ НАЙДЕН',need:'НУЖНО',artist:'Мастер',combo:'Серия слияний',painting:'Рисует',coins:'МОНЕТЫ'},
    en:{loc:'DISTRICT 01 · LEVEL',old:'Old Courtyard',under:'Underpass Studio',rooftop:'Rooftop District',wall:'WALL',artists:['artist','artists','artists'],active:'Making new masterpieces',working:'ARTISTS AT WORK',idle:'WAITING FOR SUPPLIES',board:'Paint Table',hint:'Drag matching tools together — or tap two items one after another.',spawn:'Fresh supplies',delivery:'Next delivery in',supplies:'Supplies improved',upTitle:'Workshop',goal:'Next wall',goalMain:'Upgrade the wall to level 3',goalSub:'Unlock the underpass studio',collection:'Tools',collectionEyebrow:'YOUR COLLECTION',auto:'Game saves automatically',saved:'Saved',bought:'Upgrade purchased!',poor:'Not enough coins yet',full:'Board is full — merge tools or expand the table',merge:'Nice! Tool upgraded',hire:'A new artist joined the crew!',artistUp:'Artists are working faster',spawnUp:'Supplies arrive faster',boardUp:'Table expanded — +4 slots',wallUp:'Wall expanded and rewards increased',location:'New location unlocked!',locked:'Upgrade the wall to level 3 first',next:'Next neighborhood',nextSub:'Unlock the rooftop district',max:'MAX',buy:'UPGRADE',hireBtn:'HIRE',artistsLabel:'ARTISTS',speedLabel:'WORK SPEED',supplyLabel:'SUPPLIES',boardLabel:'TABLE SPACE',wallLabel:'GRAFFITI WALL',upDescHire:'Another artist for the wall',upDescEff:'Faster art and bigger rewards',upDescSupply:'Pencils arrive more often',upDescBoard:'An extra row of tools',upDescWall:'A fresh wall and richer rewards',collected:'DISCOVERED',need:'NEED',artist:'Artist',combo:'Merge streak',painting:'Painting',coins:'COINS'}
  };
  const initial = {coins:35,items:Array(16).fill(0),capacity:16,artists:1,efficiency:1,supply:1,wall:1,spawnAt:Date.now()+24000,discovered:[true,false,false,false,false,false],drawings:0,combo:0,lastMerge:0,language:'ru',lastSave:Date.now(),jobs:[]};
  let s;
  try { const saved=JSON.parse(localStorage.getItem('graffiti-merge-save')); s=Object.assign({},initial,saved); if(!Array.isArray(s.items))s.items=initial.items.slice(); s.items=Array.from({length:Math.max(s.capacity,16)},(_,i)=>s.items[i]||0); s.capacity=Math.max(16,Math.min(24,s.capacity||16)); s.jobs=Array.isArray(s.jobs)?s.jobs:[]; s.artists=Math.max(1,s.artists||1); s.language=s.language==='en'?'en':'ru'; } catch {s={...initial,items:initial.items.slice()};}
  s.jobs=s.jobs.slice(0,s.artists);
  const t=()=>translations[s.language];
  let selected=-1, dragFrom=-1, toastTimer, lastFrame=performance.now(), confetti=[], soundCtx=null, scene=$('scene'),ctx=scene.getContext('2d');
  const spawnDelay=()=>Math.max(9000,24000-(s.supply-1)*2500);
  function save(){s.lastSave=Date.now();try{localStorage.setItem('graffiti-merge-save',JSON.stringify(s));}catch{} $('save-status').textContent=t().saved;setTimeout(()=>{$('save-status').textContent=t().auto},900);}
  function notify(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1650);}
  function sound(freq=520,duration=.07,type='sine'){try{soundCtx=soundCtx||new(window.AudioContext||window.webkitAudioContext)();const o=soundCtx.createOscillator(),g=soundCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,soundCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,soundCtx.currentTime+duration);o.connect(g);g.connect(soundCtx.destination);o.start();o.stop(soundCtx.currentTime+duration);}catch{}}
  function fmt(n){return Math.floor(n).toLocaleString(s.language==='ru'?'ru-RU':'en-US');}
  function plural(n){if(s.language==='en')return n===1?0:1;const a=n%10,b=n%100;return a===1&&b!==11?0:a>=2&&a<=4&&(b<12||b>14)?1:2;}
  function price(kind){return ({hire:Math.round(155*Math.pow(1.82,s.artists-1)),eff:Math.round(105*Math.pow(1.72,s.efficiency-1)),supply:Math.round(130*Math.pow(1.78,s.supply-1)),board:Math.round(210*Math.pow(1.9,(s.capacity-16)/4)),wall:Math.round(180*Math.pow(2.05,s.wall-1))})[kind];}
  function makeJob(level=1){return {level,progress:0,duration:Math.max(12,29-(s.efficiency-1)*2.1)*1000*(1+(level-1)*.055),seed:Math.random()*1000,color:['#e4b54e','#df6553','#6796a1','#90a45d','#ba79a2'][Math.floor(Math.random()*5)]};}
  function offline(){const elapsed=Math.min(3*60*60*1000,Math.max(0,Date.now()-(s.lastSave||Date.now())));if(elapsed<90000)return;let payout=Math.floor(elapsed/24000)*s.artists*(7+s.wall*2)*s.efficiency; if(payout>0){s.coins+=payout;setTimeout(()=>notify((s.language==='ru'?'Пока тебя не было: +':'While away: +')+fmt(payout)+' ¢'),900);}}
  offline();
  function render(){const tr=t();$('coins').textContent=fmt(s.coins);$('loc-eyebrow').textContent=`${tr.loc} ${String(s.wall).padStart(2,'0')}`;$('location-name').textContent=s.wall<3?tr.old:s.wall<5?tr.under:tr.rooftop;$('wall-label').textContent=`${tr.wall} ${s.wall}`;$('scene-level').textContent=`✦ ${s.wall}`;$('artist-count').textContent=s.artists;$('artist-word').textContent=tr.artists[plural(s.artists)];$('artist-subtitle').textContent=tr.active;$('scene-status').textContent=s.jobs.some(j=>j)?tr.working:tr.idle;
    const low=Math.max(5,Math.round((8+s.wall*2)*s.efficiency)), high=Math.round(low*1.9);$('earn-range').textContent=`${low}–${high}`;$('board-title').textContent=tr.board;$('board-hint').textContent=tr.hint;$('spawn-label').textContent=tr.spawn;$('upgrade-title').textContent=tr.upTitle;$('goal-title').textContent=tr.goal;$('collection-title').textContent=tr.collection;$('collection-eyebrow').textContent=tr.collectionEyebrow;$('save-status').textContent=tr.auto;
    const board=$('board');board.innerHTML='';board.style.gridTemplateColumns='repeat(4,1fr)';for(let i=0;i<s.capacity;i++){const cell=document.createElement('div');cell.className='board-cell'+(selected===i?' selected':'');cell.dataset.index=i;cell.setAttribute('role','gridcell');cell.setAttribute('aria-label',s.items[i]?`${toolNames[s.items[i]-1]}, уровень ${s.items[i]}`:'Пустая ячейка');if(s.items[i]){const icon=document.createElement('span');icon.className='tool';icon.textContent=toolIcons[s.items[i]-1]||'✳';icon.style.color=toolColors[s.items[i]-1];const lv=document.createElement('span');lv.className='level-tag';lv.textContent='LV '+s.items[i];cell.append(icon,lv);}cell.addEventListener('pointerdown',e=>onPointerDown(e,i));cell.addEventListener('pointerup',e=>onPointerUp(e,i));cell.addEventListener('pointerenter',()=>{if(dragFrom>=0)cell.classList.add('drag-over')});cell.addEventListener('pointerleave',()=>cell.classList.remove('drag-over'));cell.addEventListener('click',()=>onCellClick(i));board.appendChild(cell);}
    $('occupied').textContent=s.items.slice(0,s.capacity).filter(Boolean).length;$('capacity').textContent=s.capacity;
    const elapsed=spawnDelay()-(s.spawnAt-Date.now());$('spawn-in').textContent=`${tr.delivery} ${Math.ceil(Math.max(0,s.spawnAt-Date.now())/1000)} ${s.language==='ru'?'сек.':'sec.'}`;$('spawn-progress').style.width=`${Math.max(0,Math.min(100,elapsed/spawnDelay()*100))}%`;
    $('item-legend').innerHTML=toolNames.slice(0,3).map((name,i)=>`<span class="legend-item"><span class="legend-icon" style="color:${toolColors[i]}">${toolIcons[i]}</span>${name}</span>`).join('');
    const upgrades=[['hire','♟',tr.artistsLabel,tr.upDescHire,price('hire'),tr.hireBtn],['eff','↗',tr.speedLabel,tr.upDescEff,price('eff'),tr.buy],['supply','✳',tr.supplyLabel,tr.upDescSupply,price('supply'),tr.buy],['board','▦',tr.boardLabel,tr.upDescBoard,price('board'),tr.buy],['wall','▤',tr.wallLabel,tr.upDescWall,price('wall'),tr.buy]];
    $('upgrades').innerHTML=upgrades.map(([key,icon,name,desc,cost,button])=>{const level=key==='hire'?s.artists:key==='eff'?s.efficiency:key==='supply'?s.supply:key==='board'?Math.floor((s.capacity-16)/4)+1:s.wall;const isMax=key==='hire'?s.artists>=6:key==='board'?s.capacity>=24:key==='wall'?s.wall>=6:key==='eff'?s.efficiency>=8:s.supply>=6;return `<div class="upgrade-row"><span class="upgrade-icon">${icon}</span><span class="upgrade-copy"><b>${name} · ${level}</b><small>${desc}</small></span><button class="buy-button" data-buy="${key}" ${isMax||s.coins<cost?'disabled':''}>${isMax?tr.max:`${button}<br><span>¢ ${fmt(cost)}</span>`}</button></div>`;}).join('');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));
